// Extract plain text from email
// Support both field naming conventions (textHtml/textPlain and html/text)
const data = $input.first().json;
let text = '';
const html = data.textHtml || data.html || '';
const textBody = data.textPlain || data.text || '';

// Fix encoding: GMX sometimes delivers UTF-8 bytes misread as Latin-1
function fixEncoding(str) {
  if (!str) return '';
  return str
    .replace(/Ã¤/g, 'ä').replace(/Ã/g, 'Ä')
    .replace(/Ã¶/g, 'ö').replace(/Ã/g, 'Ö')
    .replace(/Ã¼/g, 'ü').replace(/Ã/g, 'Ü')
    .replace(/Ã/g, 'ß')
    .replace(/â/g, '—').replace(/â/g, '–')
    .replace(/â/g, "'").replace(/â/g, "'")
    .replace(/â/g, '„').replace(/â/g, '“')
    .replace(/â¦/g, '…');
}

if (textBody && textBody.trim().length > 0) {
  text = fixEncoding(textBody);
} else if (html) {
  text = fixEncoding(
    html
      .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '')
      .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '')
      .replace(/<br\s*\/?>/gi, '\n')
      .replace(/<\/p>/gi, '\n\n')
      .replace(/<\/div>/gi, '\n')
      .replace(/<\/li>/gi, '\n')
      .replace(/<[^>]+>/g, '')
      .replace(/&nbsp;/g, ' ')
      .replace(/&amp;/g, '&')
      .replace(/&lt;/g, '<')
      .replace(/&gt;/g, '>')
      .replace(/&quot;/g, '"')
      .replace(/&auml;/g, 'ä').replace(/&Auml;/g, 'Ä')
      .replace(/&ouml;/g, 'ö').replace(/&Ouml;/g, 'Ö')
      .replace(/&uuml;/g, 'ü').replace(/&Uuml;/g, 'Ü')
      .replace(/&szlig;/g, 'ß')
      .replace(/&mdash;/g, '—').replace(/&ndash;/g, '–')
      .replace(/&#\d+;/g, '')
      .replace(/\n{3,}/g, '\n\n')
      .trim()
  );
}

const subject = fixEncoding(data.subject || 'Kein Betreff');
const date = data.date;
const from = data.from;

const mailDate = new Date(date);
const dateStr = mailDate.toISOString().split('T')[0];

const slug = subject
  .toLowerCase()
  .replace(/[äÄ]/g, 'ae')
  .replace(/[öÖ]/g, 'oe')
  .replace(/[üÜ]/g, 'ue')
  .replace(/ß/g, 'ss')
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/^-|-$/g, '')
  .substring(0, 40);

return {
  json: {
    text,
    subject,
    date: dateStr,
    from,
    slug,
    branchName: `aktuelles/${dateStr}-${slug}`
  }
};

// Parse AI Agent response - extract JSON from output
const response = $input.first().json;
const output = response.output || response.text || '';

// Extract JSON from response (might be wrapped in markdown code block)
let jsonStr = output;
const jsonMatch = output.match(/```(?:json)?\s*([\s\S]*?)```/);
if (jsonMatch) {
  jsonStr = jsonMatch[1].trim();
} else {
  const objMatch = output.match(/(\{[\s\S]*\})/);
  if (objMatch) {
    jsonStr = objMatch[1];
  }
}

let items = [];
try {
  const parsed = JSON.parse(jsonStr);
  items = parsed.items || [];
} catch (e) {
  // If JSON parsing fails, continue with empty items
  items = [];
}

const mailDate = $('Text extrahieren').first().json.date;
const branchName = $('Text extrahieren').first().json.branchName;
const subject = $('Text extrahieren').first().json.subject;

const beitraege = items.filter(i => i.type === 'beitrag');
const quickinfos = items.filter(i => i.type === 'quickinfo');
const termine = items.filter(i => i.type === 'termin');

const files = [];

for (const item of [...beitraege, ...quickinfos]) {
  const frontmatter = [
    '---',
    'title: "' + item.title + '"',
    'date: ' + mailDate,
    'description: "' + (item.description || '') + '"',
    'tags: [' + (item.tags || []).map(t => '"' + t + '"').join(', ') + ']'
  ];
  if (item.type === 'quickinfo') {
    frontmatter.push('quickinfo: true');
  }
  frontmatter.push('---');
  frontmatter.push('');
  frontmatter.push(item.body || '');
  frontmatter.push('');

  files.push({
    path: 'content/aktuelles/' + mailDate + '-' + item.slug + '.md',
    content: frontmatter.join('\n'),
    type: item.type,
    title: item.title
  });
}

let prBody = '## Neue Inhalte\n\n';
prBody += '| Typ | Datei | Titel |\n|-----|-------|-------|\n';
for (const f of files) {
  prBody += '| ' + f.type + ' | `' + f.path + '` | ' + f.title + ' |\n';
}
for (const t of termine) {
  prBody += '| termin | `content/termine/_index.md` | ' + t.title + ' |\n';
}
prBody += '\n---\nAutomatisch erstellt aus Mail vom ' + mailDate;

return {
  json: {
    files,
    termine,
    branchName,
    mailDate,
    subject,
    prBody,
    stats: {
      beitraege: beitraege.length,
      quickinfos: quickinfos.length,
      termine: termine.length
    }
  }
};

// Get existing termine file content and merge with new termine
const termineFile = $('Termine laden').first().json;
const existingContent = Buffer.from(termineFile.content, 'base64').toString('utf-8');
const existingSha = termineFile.sha;

const parsed = $('Bilder einfuegen').first().json;
const newTermine = parsed.termine;
const files = parsed.files;
const branchName = parsed.branchName;

// Parse existing YAML events from frontmatter
const frontmatterMatch = existingContent.match(/^---\n([\s\S]*?)\n---/);
let yamlContent = frontmatterMatch ? frontmatterMatch[1] : '';

// Simple duplicate check: extract existing event dates+titles
const existingEvents = [];
const eventRegex = /- title: \"([^\"]*)\"|  date: (\d{4}-\d{2}-\d{2})/g;
let match;
let currentTitle = '';
while ((match = eventRegex.exec(yamlContent)) !== null) {
  if (match[1]) currentTitle = match[1];
  if (match[2]) existingEvents.push({ title: currentTitle.toLowerCase(), date: match[2] });
}

// --- Handle replacements: remove old events that are being corrected ---
let contentAfterReplacements = existingContent;
const replacedTermine = newTermine.filter(t => t.replaces);
let replacementCount = 0;

for (const t of replacedTermine) {
  const searchTitle = t.replaces.title_contains.toLowerCase();
  const searchDate = t.replaces.date;
  // Build regex to match a full event block: from '  - title:' to the next '  - title:' or closing '---'
  // Each event block starts with '  - title: "..."' and includes indented fields until next event or end
  const eventBlockRegex = new RegExp(
    '  - title: \"[^\"]*' + searchTitle.replace(/[.*+?^${}()|[\\]\\]/g, '\\$&') + '[^\"]*\"\\n' +
    '(?:    [a-z]+: [^\\n]*\\n)*',
    'gi'
  );
  const blocks = contentAfterReplacements.match(eventBlockRegex) || [];
  for (const block of blocks) {
    if (block.includes('date: ' + searchDate)) {
      contentAfterReplacements = contentAfterReplacements.replace(block, '');
      replacementCount++;
    }
  }
}

// Filter out duplicate termine (skip if already exists with same date+title)
const uniqueTermine = newTermine.filter(t => {
  // Replacements are always added (old entry was already removed above)
  if (t.replaces) return true;
  const isDuplicate = existingEvents.some(e =>
    e.date === t.date &&
    (e.title.includes(t.title.toLowerCase().substring(0, 10)) ||
     t.title.toLowerCase().includes(e.title.substring(0, 10)))
  );
  return !isDuplicate;
});

// Append new termine to YAML
let updatedContent = contentAfterReplacements;
if (uniqueTermine.length > 0) {
  const closingIndex = updatedContent.lastIndexOf('---');
  let newYaml = '';
  for (const t of uniqueTermine) {
    newYaml += '  - title: \"' + t.title + '\"\n';
    newYaml += '    date: ' + t.date + '\n';
    if (t.time) newYaml += '    time: \"' + t.time + '\"\n';
    if (t.detail) newYaml += '    detail: \"' + t.detail + '\"\n';
    newYaml += '    category: \"' + (t.category || 'event') + '\"\n';
  }
  updatedContent = updatedContent.substring(0, closingIndex) + newYaml + '---';
}

const hasChanges = uniqueTermine.length > 0 || replacementCount > 0;

return {
  json: {
    files,
    branchName,
    mailDate: parsed.mailDate,
    subject: parsed.subject,
    prBody: parsed.prBody,
    stats: parsed.stats,
    termineContent: updatedContent,
    termineSha: existingSha,
    hasNewTermine: hasChanges,
    skippedTermine: newTermine.length - uniqueTermine.length,
    replacedTermine: replacementCount
  }
};

// Build a single Git tree with all files
const data = $('Termine zusammenfuehren').first().json;
const tree = [];
// Git/POSIX convention; nuliga-sync's frontmatter regex used to choke on a missing final newline
const withNewline = s => s.endsWith('\n') ? s : s + '\n';

// Add article/quickinfo files
for (const file of data.files) {
  tree.push({
    path: file.path,
    mode: '100644',
    type: 'blob',
    content: withNewline(file.content)
  });
}

// Add updated termine file if needed
if (data.hasNewTermine) {
  tree.push({
    path: 'content/termine/_index.md',
    mode: '100644',
    type: 'blob',
    content: withNewline(data.termineContent)
  });
}

// Get the base tree SHA from the branch
const branchSha = $('Branch erstellen').first().json.object.sha;

return {
  json: {
    tree,
    base_tree: branchSha,
    branchName: data.branchName,
    mailDate: data.mailDate,
    prBody: data.prBody,
    stats: data.stats
  }
};

// Drawn post images: house-style SVG template, allow-list sanitiser and text helpers.
// Plain script without require/import: its source is pasted verbatim into n8n Code nodes
// (see scripts/sync-n8n.js), and module.exports is only used by the Node tests.

var ALLOWED_ELEMENTS = ['g', 'path', 'circle', 'ellipse', 'rect', 'line', 'polyline', 'polygon',
  'linearGradient', 'radialGradient', 'stop', 'defs'];

var ALLOWED_ATTRIBUTES = ['id', 'd', 'cx', 'cy', 'r', 'rx', 'ry', 'fx', 'fy', 'x', 'y', 'x1', 'y1',
  'x2', 'y2', 'width', 'height', 'points', 'fill', 'fill-opacity', 'fill-rule', 'stroke',
  'stroke-width', 'stroke-linecap', 'stroke-linejoin', 'stroke-opacity', 'stroke-dasharray',
  'opacity', 'transform', 'offset', 'stop-color', 'stop-opacity', 'gradientUnits',
  'gradientTransform'];

var MAX_SVG_LENGTH = 8192;
var DRAW_MODEL = 'claude-sonnet-5-5';
var MAX_BODY_CHARS = 3000;

var TEMPLATE_HEAD =
  '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 510 200" width="510" height="200">\n' +
  '<defs>' +
  '<linearGradient id="tpl-bg" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#153266"/><stop offset="1" stop-color="#0a1628"/></linearGradient>' +
  '<radialGradient id="tpl-glow" cx=".5" cy=".55" r=".5"><stop offset="0" stop-color="#3a7bd5" stop-opacity=".45"/><stop offset="1" stop-color="#3a7bd5" stop-opacity="0"/></radialGradient>' +
  '</defs>\n' +
  '<rect width="510" height="200" fill="url(#tpl-bg)"/>\n' +
  '<g stroke="#fff" stroke-opacity=".12" stroke-width="2" fill="none"><rect x="60" y="25" width="390" height="150"/><path d="M255 25 V175 M60 45 H450 M60 155 H450 M157 45 V155 M352 45 V155 M157 100 H352"/></g>\n' +
  '<ellipse cx="255" cy="110" rx="170" ry="90" fill="url(#tpl-glow)"/>\n';

// Returns the outermost <g>...</g> from model output (prose and code fences ignored).
function extractMotif(text) {
  if (!text) return null;
  var re = /<(\/?)g(?=[\s>\/])[^>]*?(\/?)>/g;
  var start = -1, depth = 0, m;
  while ((m = re.exec(text)) !== null) {
    var closing = m[1] === '/', selfClosing = m[2] === '/';
    if (start === -1) {
      if (closing) continue;
      start = m.index;
      if (selfClosing) return m[0];
      depth = 1;
      continue;
    }
    if (selfClosing) continue;
    depth += closing ? -1 : 1;
    if (depth === 0) return text.slice(start, re.lastIndex);
  }
  return null;
}

function cleanAttributes(raw, idPrefix) {
  var out = [];
  var re = /([a-zA-Z:-]+)\s*=\s*(?:"([^"]*)"|'([^']*)')/g, m;
  while ((m = re.exec(raw)) !== null) {
    var name = m[1], value = m[2] !== undefined ? m[2] : m[3];
    if (ALLOWED_ATTRIBUTES.indexOf(name) === -1) continue;
    if (/["&]/.test(value)) continue;
    if (name === 'id') {
      if (!/^[A-Za-z0-9_-]+$/.test(value)) continue;
      value = idPrefix + '-' + value;
    } else if (value.indexOf('url(') !== -1) {
      var local = /^url\(#([A-Za-z0-9_-]+)\)$/.exec(value.trim());
      if (!local) continue;
      value = 'url(#' + idPrefix + '-' + local[1] + ')';
    }
    out.push(name + '="' + value + '"');
  }
  return out.length ? ' ' + out.join(' ') : '';
}

// Rebuilds markup from allow-listed elements/attributes only. Text nodes are dropped
// (motifs have none). Returns null for empty or unbalanced input.
function sanitizeMotif(markup, idPrefix) {
  if (!markup || !markup.trim()) return null;
  var src = markup
    .replace(/<!--[\s\S]*?-->/g, '')
    .replace(/<!\[CDATA\[[\s\S]*?\]\]>/g, '')
    .replace(/<\?[\s\S]*?\?>/g, '')
    .replace(/<![^>]*>/g, '');
  var re = /<(\/?)([a-zA-Z][a-zA-Z0-9]*)([^>]*?)(\/?)>/g;
  var stack = [], dropDepth = 0, out = '', m;
  while ((m = re.exec(src)) !== null) {
    var closing = m[1] === '/', name = m[2], selfClosing = m[4] === '/';
    var allowed = ALLOWED_ELEMENTS.indexOf(name) !== -1;
    if (closing) {
      if (!stack.length || stack[stack.length - 1] !== name) return null;
      stack.pop();
      if (dropDepth > 0) { dropDepth--; continue; }
      out += '</' + name + '>';
      continue;
    }
    if (dropDepth > 0 || !allowed) {
      if (!selfClosing) { stack.push(name); dropDepth++; }
      continue;
    }
    var attrs = cleanAttributes(m[3], idPrefix);
    if (selfClosing) {
      out += '<' + name + attrs + '/>';
    } else {
      stack.push(name);
      out += '<' + name + attrs + '>';
    }
  }
  if (stack.length) return null;
  return out ? out : null;
}

function wrapSvg(motif) {
  return TEMPLATE_HEAD + motif + '\n</svg>\n';
}

function renderSvg(rawText, idPrefix) {
  var motif = sanitizeMotif(extractMotif(rawText), idPrefix);
  if (!motif) return null;
  var svg = wrapSvg(motif);
  // shortcut: counts UTF-16 units, not bytes; sanitized output is ASCII in practice
  return svg.length < MAX_SVG_LENGTH ? svg : null;
}

function imagePaths(postPath) {
  var base = postPath.split('/').pop().replace(/\.md$/, '');
  return {
    file: 'static/images/news/gezeichnet/' + base + '.svg',
    url: '/images/news/gezeichnet/' + base + '.svg',
  };
}

function addImageToFrontMatter(md, url) {
  var end = md.indexOf('\n---', 3);
  if (!md.startsWith('---') || end === -1) return md;
  if (/^image:/m.test(md.slice(0, end))) return md;
  return md.slice(0, end) + '\nimage: "' + url + '"' + md.slice(end);
}

function addPrRows(prBody, rows) {
  var idx = prBody.lastIndexOf('\n\n---\n');
  if (idx === -1) return prBody + '\n' + rows.join('\n');
  return prBody.slice(0, idx) + '\n' + rows.join('\n') + prBody.slice(idx);
}

// Anthropic Messages API request body for one post.
function buildDrawRequest(post, systemPrompt, examples) {
  var system = systemPrompt + (examples || []).map(function (e) {
    return '\n\n<example>\n' + e.trim() + '\n</example>';
  }).join('');
  var content = 'Title: ' + (post.title || '') + '\nDescription: ' + (post.description || '') +
    '\n\n' + String(post.body || '').slice(0, MAX_BODY_CHARS);
  return {
    model: DRAW_MODEL,
    max_tokens: 4000,
    system: system,
    messages: [{ role: 'user', content: content }],
  };
}

if (typeof module !== 'undefined') {
  module.exports = {
    ALLOWED_ELEMENTS: ALLOWED_ELEMENTS, ALLOWED_ATTRIBUTES: ALLOWED_ATTRIBUTES,
    extractMotif: extractMotif, sanitizeMotif: sanitizeMotif, wrapSvg: wrapSvg,
    renderSvg: renderSvg, imagePaths: imagePaths,
    addImageToFrontMatter: addImageToFrontMatter, addPrRows: addPrRows,
    buildDrawRequest: buildDrawRequest, DRAW_MODEL: DRAW_MODEL,
  };
}

var SYSTEM_PROMPT = "You draw small flat illustrations for news posts of a tennis club website (TC Blau-Weiss Attendorn). For the post below, draw ONE simple motif that shows what the post is about.\n\nOutput rules:\n- Reply with exactly one SVG `<g>...</g>` element and nothing else: no prose, no code fences, no `<svg>` wrapper.\n- Coordinate space is 510 x 200 (x to the right, y down). The background (dark blue gradient, faint court lines, soft glow) is added for you; draw only the motif on top of it.\n- Keep the whole motif inside x 130-380 and y 20-180 so it survives cropping. Rest objects on an imaginary ground line around y 170.\n- Allowed elements: g, path, circle, ellipse, rect, line, polyline, polygon, defs, linearGradient, radialGradient, stop. Allowed attributes are geometry, fill, stroke, opacity, transform and gradient attributes. Gradients may be referenced as `url(#id)` with ids you define yourself.\n- Colours only from this palette: #ffffff, #dceafb, #a8ccf5, #6ba3eb, #3a7bd5, #1e56a0, #0f2240. The motif must be light (mostly white and pale blue) so it stands out on dark blue.\n- Tennis balls are white with blue seams, never yellow.\n- Flat, simple, friendly shapes, like a modern icon. At most about 40 elements. Recognisable at 340 x 220 pixels.\n- Never draw text, letters, digits, logos, brand marks or faces. Show people at most as simple silhouettes, preferably not at all; prefer objects (rackets, balls, nets, calendars, trophies, tools, food, buildings, weather).\n\nThe examples show the expected style and size.";
